def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); asymmetric=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        q=(y+dy,x+dx)
                        if (dy or dx) and 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] != 0 and q not in seen:
                            seen.add(q); stack.append(q)
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            cellset=set(cells)
            crop=[[grid[y][x] if (y,x) in cellset else 0 for x in range(c0,c1+1)] for y in range(r0,r1+1)]
            if crop != [row[::-1] for row in crop]: asymmetric.append(crop)
    assert len(asymmetric)==1, len(asymmetric)
    return asymmetric[0]
